def total_cents(amounts):
    """Sum a list of decimal amount strings like '12.30' and return integer cents."""
    total = 0
    for a in amounts:
        total += int(float(a) * 100)  # bug: float truncation, e.g. '0.29' -> 28
    return total

import unittest
from invoice import total_cents


class TestInvoice(unittest.TestCase):
    def test_simple(self):
        self.assertEqual(total_cents(["1.00", "2.50"]), 350)

    def test_rounding(self):
        self.assertEqual(total_cents(["0.29", "0.57"]), 86)


if __name__ == "__main__":
    unittest.main()

